style.css:
@-moz-document domain("open.spotify.com") {
/* Agregar imagen de fondo */
    body,
    .Root__main-view,
    .main-view-container,
    .main-view {
        background: url("https://i.pinimg.com/736x/2b/bc/ea/2bbcea2217b809f2ee07679453fa2166.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Cambiar el color de la barra lateral */
    .Root__nav-bar,
    .Sidebar,
    .main-nav {
        background-color: rgba(248, 187, 208, 0.8) !important; /* Rosa pastel con transparencia */
    }

    /* Cambiar el color del reproductor */
    .PlayerBar,
    .player-controls__buttons,
    .playback-bar {
        background-color: rgba(244, 143, 177, 0.8) !important; /* Rosa fuerte con transparencia */
    }

    /* Cambiar los colores de los textos */
    .track-name,
    .artist-name,
    .main-navLink-text,
    .Root__now-playing-bar {
        color: #c2185b !important; /* Rosa oscuro */
    }

    /* Cambiar TODOS los botones verdes a #ffbfea */
    .control-button,
    .play-button,
    .pause-button,
    .Button-ytm,
    .main-playButton-button,
    .main-addButton-button,
    .progress-bar__fg {
        background-color: #ffbfea !important;
        color: white !important; /* Para mejor visibilidad */
        border: none !important;
    }

    /* Cambiar los bordes y resaltar iconos */
    .icon,
    .tracklist-row__button {
        filter: hue-rotate(300deg); /* Ajuste de color */
    }
}
